class Solution {
public:
    vector<int> findPermutation(string s) {
        int n = s.size();
        vector<int> res(n + 1);
        for (int i = 0; i <= n; ++i) res[i] = i + 1;
        int i = 0;
        while (i < n) {
            if (s[i] == 'D') {
                int start = i;
                while (i < n && s[i] == 'D') i++;
                reverse(res.begin() + start, res.begin() + i + 1);
            } else {
                i++;
            }
        }
        return res;
    }
};

class Solution {
    public int[] findPermutation(String s) {
        int n = s.length();
        int[] res = new int[n + 1];
        for (int i = 0; i <= n; i++) res[i] = i + 1;
        int i = 0;
        while (i < n) {
            if (s.charAt(i) == 'D') {
                int start = i;
                while (i < n && s.charAt(i) == 'D') i++;
                reverse(res, start, i);
            } else {
                i++;
            }
        }
        return res;
    }

    private void reverse(int[] a, int l, int r) {
        while (l < r) {
            int t = a[l];
            a[l++] = a[r];
            a[r--] = t;
        }
    }
}

