var findPermutation = function(s) {
    const n = s.length;
    const res = Array.from({ length: n + 1 }, (_, i) => i + 1);
    let i = 0;
    while (i < n) {
        if (s[i] === 'D') {
            const start = i;
            while (i < n && s[i] === 'D') i++;
            let l = start, r = i;
            while (l < r) {
                const tmp = res[l];
                res[l++] = res[r];
                res[r--] = tmp;
            }
        } else {
            i++;
        }
    }
    return res;
};
